'use strict';

// 覆蓋擴充 B：TSC、Argox、Zebra、TOSHIBA、SATO。

addRepairKB({id:'tsc-alpha3r',brand:'TSC',models:['Alpha-3R'],category:'行動式／電池／連線',title:'Alpha-3R｜無法開機、電池續航差、走紙/列印、藍牙連線',severity:'行動機',sources:['tsc_alpha'],summary:'Alpha-3R 是行動熱感機，排查要先把 Battery/Charger、Printer 本體、Media 與無線連線分開。電池老化不能只靠「充得進去」判斷。',keyFacts:['原廠提供 Alpha-3R 專用電池與充電配件。','行動機完全不開機時先做電池/充電器交叉，再懷疑 Mainboard。','紙會走但不印先確認熱感紙面與 Printhead 清潔。'],engineering:['續航異常要記錄滿充後實際工作時數、休眠與無線使用情境。','藍牙配對成功但 App 不印要再查 Driver/SDK/Port/應用層。'],verify:['冷開機 5 次正常','滿充後續航符合現場需求','連續列印穩定','藍牙/USB 實際工作正常'],flow:[['電源分流','完全不開或續航差。',['電源正常','完全不開','很快沒電'],'先判 Battery。'],['電池/充電交叉','已知正常 Battery/Charger 交叉。',['換電池正常','換充電器正常','仍異常'],'先耗材式零件。'],['熱感紙/走紙','FEED 與紙面方向。',['正常','不走紙','走紙但空白'],'空白先紙面/Head。'],['清潔 Printhead/Platen','行動機紙粉也會影響品質。',['恢復','仍異常'],'再進硬體。'],['藍牙/USB 分流','配對、裝置辨識、App/Driver。',['恢復','仍異常','不適用'],'連線層不要跟 Printer 本體混。'],['深入硬體','Power board/Mainboard/Drive 需依 Service 資料。',['硬體方向高','已修復'],'避免憑經驗量未知 Pin。']]});

addRepairKB({id:'tsc-mb240t-mb340t',brand:'TSC',models:['MB240T','MB340T'],category:'工業型／Sensor／Cutter',title:'MB240T/MB340T｜校正、TPH、Cutter、LAN、走紙異常',severity:'高價值',sources:['tsc_mb'],summary:'MB240T/MB340T 工業型排查可利用 Sensor calibration、內建診斷與 TSC Console，把耗材/Sensor、Printhead、Cutter 與 LAN 分開。',keyFacts:['MB240 系列已有停產/替代資訊，但仍有服務支援週期。','Cutter/Peel/Wi-Fi 等為可選模組，故障前先確認實際機器是否安裝。','TPH/品質問題先用測試圖與清潔，不直接換 Head。'],engineering:['工業機走紙偏、皺碳需同時檢查壓力、Platen、Media Guide 與 Ribbon path。'],verify:['50 張無跳標','測試圖正常','Cutter/Peel 連續動作正常','LAN 穩定'],flow:[['確認裝備/模式','Cutter/Peel/LAN 是否實際存在，Print Mode 正確。',['正確','已修正'],'避免查不存在的模組。'],['Sensor Calibration','紙材類型、Sensor 位置/清潔後校正。',['成功','失敗'],'失敗再硬體。'],['列印品質測試','清 Head/Platen 後印固定測試。',['正常','固定白線','單側淡/皺碳'],'分流。'],['Cutter/Peel 分流','Mode→清潔→Sensor/Home→Motor/Gear。',['恢復','仍異常','不適用'],'斷電清模組。'],['LAN 分流','Link→IP→Ping→Port→Queue。',['恢復','仍異常','不適用'],'先網路層。'],['硬體收斂','Sensor/Head/Motor/線束/主板逐層。',['已修復','需換件'],'主板最後。']]});

addRepairKB({id:'tsc-ttp244pro',brand:'TSC',models:['TTP-244 PRO'],category:'桌上型舊機／校正',title:'TTP-244 PRO｜紅燈、一直走紙、碳帶/紙張、USB 不印',severity:'舊機常見',sources:['tsc_ttp'],summary:'TTP-244 PRO 類舊桌機適合用最小化流程：LED/FEED 狀態→耗材→校正→自測→Driver/USB，再進 Sensor/Drive。',keyFacts:['一直走紙多半先查紙種/Sensor/Calibration。','本機自測正常但 Windows 不印，優先 Driver/Port/Queue。','紙走但空白要分碳帶面向、熱轉印設定與 Printhead。'],engineering:['老機電源變壓器、Platen 與 USB 接頭磨損也要列入交叉測試。'],verify:['FEED 一張','自測正常','Windows Test Page 正常','連印 50 張'],flow:[['看 LED / FEED','記錄燈號與按 FEED 行為。',['正常走一張','一直走紙','不走紙','紅燈'],'先記現象。'],['確認紙/碳帶','模式與安裝。',['正確','已修正'],'基礎。'],['執行 Calibration','依原廠系列流程。',['成功','失敗'],'失敗清 Sensor。'],['印 Self-test','不經電腦。',['正常','異常'],'切開 Driver。'],['USB/Driver','換線/Port/電腦，重建 Driver/Port。',['恢復','仍異常','不適用'],'先外部。'],['硬體收斂','Sensor、Motor、Platen、電源、Mainboard。',['已修復','需換件'],'依機型手冊。']]});

addRepairKB({id:'argox-ix4pro-core',brand:'Argox',models:['iX4-200 Pro','iX4-240 Pro','iX4-250 Pro','iX4-350 Pro'],category:'工業型／校正／品質',title:'iX4 Pro｜Media Calibration、Ribbon、Printhead、Cutter、LAN',severity:'高價值',sources:['argox_ix4pro','argox_manuals'],summary:'iX4 Pro 原廠提供 User Manual、Printer Tool 與 Cutter/Peeler/WLAN 文件。排查時可用 Printer Tool 配合機器本體，把 Sensor、品質、選配模組與連線分開。',keyFacts:['Printer Tool 是官方設定工具，可用來確認設定與通訊。','Cutter/Peeler/WLAN 為選配，先確認模組存在與設定。','品質異常先清 Printhead/Platen、固定速度/濃度，再查壓力/耗材。'],engineering:['工業機皺碳/偏紙常是耗材路徑、壓力、Platen/導紙共同造成。'],verify:['Calibration 正常','100 張定位穩定','Ribbon 不皺/不斷','LAN/USB 正常','選配模組正常'],flow:[['確認耗材/模式','Media Type、Print Method、Ribbon 路徑。',['正確','已修正'],'先排設定。'],['執行 Media Calibration','用機器或 Printer Tool。',['成功','失敗'],'失敗清 Sensor/換紙。'],['列印品質基準','固定同一耗材、速度、濃度。',['正常','太淡','固定白線','皺碳/單側淡'],'分類。'],['清潔/機構','Printhead、Platen、Guide、壓力、Ribbon path。',['恢復','仍異常'],'先機構。'],['Cutter/Peel/LAN 分流','模組存在才查設定→Sensor/Home→Motor；LAN 走 Link/IP/Ping/Port。',['恢復','仍異常','不適用'],'分模組。'],['硬體收斂','Sensor/Head/Motor/線束/Mainboard。',['已修復','需換件'],'依 iX4 Pro 手冊。']]});

addRepairKB({id:'argox-p4pro-core',brand:'Argox',models:['P4-250 Pro','P4-350 Pro','P4-650 Pro'],category:'桌上型／校正／高解析',title:'P4 Pro｜紙張校正、印太淡、固定白線、USB/LAN、Cutter',severity:'高頻',sources:['argox_p4pro','argox_manuals'],summary:'P4 Pro 官方提供繁中/英文 User Manual 與 Printer Tool。桌上型高解析機種要先把紙材/校正與速度/濃度基準做好，再判 Printhead、Platen 或軟體。',keyFacts:['P4 Pro 有官方 Printer Tool 可協助設定。','高 dpi 機種對小標籤、紙張一致性、速度/熱量更敏感。','固定白線清潔後仍存在才提高 Printhead 嫌疑。'],engineering:['白色/特殊樹脂碳帶屬耗材匹配問題，不能只用 Darkness 數字跨品牌比較。'],verify:['FEED 一張','條碼可讀','固定測試圖正常','USB/LAN/Cutter 正常'],flow:[['確認紙/碳帶與模式','紙材、Ribbon 面向、Print Method。',['正確','已修正'],'先外部。'],['Media Calibration','用機器/Printer Tool。',['成功','失敗'],'失敗清 Sensor。'],['品質基準','固定速度/濃度，必要時降速。',['改善','無改善'],'高解析先降速比較。'],['清 Head/Platen','重印同一圖。',['正常','固定白線','單側淡/皺碳'],'分類。'],['連線/Cutter','USB/LAN 交叉；Cutter 查 Mode/卡紙/Home。',['恢復','仍異常','不適用'],'先設定再硬體。'],['硬體收斂','Sensor/Head/Platen/線束/主板。',['已修復','需換件'],'依原廠文件。']]});

addRepairKB({id:'argox-cx-core',brand:'Argox',models:['CX-3140 Pro','CX-2140 Pro'],category:'桌上型／自測／Cutter',title:'CX-2140 Pro/CX-3140 Pro｜Calibration、Self-test、Dump、Cutter、列印品質',severity:'高頻',sources:['argox_cp','argox_manuals'],summary:'CX 與 CP-EX 共用的原廠文件包含 Calibration、Self-test、Dump 等診斷概念；遇到亂碼、一直送紙、切刀或品質問題，可先用單機模式切開 Host/Driver。',keyFacts:['Dump Mode 可用來判斷收到的資料內容，不代表 Printer 機構正常。','Self-test 正常但應用程式不印，優先查 Driver/Port/Emulation。','Cutter 先排 Mode/紙屑，再查 Home/Motor。'],engineering:['不同韌體版本按鍵組合可能有差異，操作前依 CX 對應手冊。'],verify:['Self-test 正常','Calibration 正常','實際軟體列印正常','Cutter 連切正常'],flow:[['執行 Self-test','先看 Printer 本體。',['正常','異常'],'正常先查 Host。'],['Calibration','紙張類型/感應器後校正。',['成功','失敗'],'一直走紙優先。'],['Dump Mode 分流','只有亂碼/指令疑慮時使用。',['資料正常','資料異常','不適用'],'資料異常查 Host/Emulation。'],['品質處理','清 Head/Platen，固定速度/濃度。',['正常','固定缺線','太淡/單側淡'],'分類。'],['Cutter','Mode→清潔→Home Sensor→Motor/Gear。',['正常','仍異常','不適用'],'斷電處理。'],['硬體收斂','Sensor/Head/Motor/線束/Mainboard。',['已修復','需換件'],'主板最後。']]});

addRepairKB({id:'zebra-zt111-baseline',brand:'Zebra',models:['ZT111'],category:'商業型／校正／品質',title:'ZT111｜Media/Ribbon、Calibration、列印品質、USB/LAN 基線',severity:'基礎覆蓋',sources:['zebra_cal','zebra_jg'],summary:'ZT111 若遇 Paper/Ribbon、跳標、品質或連線，可沿 Zebra 共通工程順序排查：Print Method/Media Type→Calibration/Sensor Profile→機構→線路；本機測試正常再查 Driver/Port。',keyFacts:['Zebra Sensor Profile 是判斷 media/ribbon 感應的重要工具。','Calibration 前先確認 Media Type/Print Method。','Driver 可覆蓋部分機器設定，需做單機 Test 對照。'],engineering:['此條目先提供安全基線，不把 ZT400/ZT600 的壓力數字硬套 ZT111。'],verify:['FEED 一張','50 張定位穩定','本機與電腦送印都正常'],flow:[['Print Method / Media Type','TT/DT、Gap/Mark/Continuous。',['正確','已修正'],'先設定。'],['Calibration','執行該機型 Media/Ribbon calibration。',['成功','失敗'],'失敗再看 Profile。'],['Sensor Profile','看 gap/mark/ribbon 變化。',['正常','波形弱/固定'],'固定提高 Sensor/線束嫌疑。'],['品質基準','清 Head/Platen，固定速度/濃度。',['正常','固定缺線','單側淡'],'分流。'],['USB/LAN','本機 Test 正常才查 Driver/Port。',['恢復','仍異常','不適用'],'切開軟硬體。'],['硬體收斂','Sensor/線束/Head/Drive/Mainboard。',['已修復','需換件'],'依 Service Manual。']]});

addRepairKB({id:'zebra-zd2xx-zd888',brand:'Zebra',models:['ZD220','ZD230','ZD888TA'],category:'桌上型／校正／USB',title:'ZD220/ZD230/ZD888TA｜紙張校正、紅燈、只走紙不印、USB 不印',severity:'高頻',sources:['zebra_cal'],summary:'Zebra 入門桌上型的高頻問題集中在耗材/校正、熱感/熱轉印設定與 USB Driver。先做 FEED/本機 Test，再決定是否進 Sensor 或電腦端。',keyFacts:['紙會走但空白要先確認 Direct Thermal/熱轉印機型與耗材面向。','本機可印但 Windows 不印，多數先查 Driver/Port/Queue。','一直走紙先查 Media Type、Sensor 與 Calibration。'],engineering:['小型機不建議在沒有 Service Manual 時直接帶電量主板。'],verify:['FEED 一張','本機 Test 正常','Windows Test Page 正常','連印 50 張'],flow:[['耗材/模式','紙材、Ribbon（若機型適用）、Media Type。',['正確','已修正'],'空白與紅燈先查。'],['Calibration','做機型對應紙張校正。',['成功','失敗'],'失敗清 Sensor。'],['本機 Test','不經電腦。',['正常','異常'],'正常轉查 Driver。'],['USB','換線/Port/電腦，裝置管理員與 Printer Port。',['恢復','仍異常','不適用'],'先外部交叉。'],['品質','清 Head/Platen。',['正常','固定白線','太淡'],'固定白線才查 Head。'],['硬體收斂','Sensor/Drive/電源/主板依手冊。',['已修復','需送修深入'],'避免盲量。']]});

addRepairKB({id:'zebra-gk-gx-gt',brand:'Zebra',models:['GX420','GX430','GK420','GT800'],category:'桌上型舊機／校正',title:'GK/GX/GT800｜紅燈、一直走紙、空白、USB、Printhead/Platen',severity:'舊機常見',sources:['zebra_cal'],summary:'GK/GX/GT 舊桌機常見紙張校正、USB Driver、Platen 老化與 Printhead 固定缺線。先做 FEED/Config Label，避免直接把 Windows 問題當機器壞。',keyFacts:['舊機 Platen 硬化/磨損會造成走紙與品質不穩。','固定白線清 Head 後仍在才提高 Printhead。','USB 完全無辨識要換線/Port/電腦交叉。'],engineering:['不同機種 reset/calibration 按鍵方式不同，依型號手冊操作。'],verify:['FEED 一張','Config Label 正常','USB 正常','50 張品質/定位穩定'],flow:[['FEED/Config Label','先看本機。',['正常','跳標/一直走','不走','空白'],'分流。'],['Media Calibration','紙種、Sensor 清潔後校正。',['成功','失敗','不適用'],'定位問題。'],['清 Head/Platen','觀察滾輪表面。',['恢復','Platen 異常','固定白線'],'老機重點。'],['USB/Driver','本機正常才做。',['恢復','仍異常','不適用'],'換線/Port/PC。'],['Drive','不走紙看 Motor/Gear/Platen。',['找到異常','仍異常','不適用'],'先機構。'],['硬體收斂','Sensor/Head/Motor/電源/Mainboard。',['已修復','需換件'],'主板最後。']]});

addRepairKB({id:'zebra-mobile-baseline',brand:'Zebra',models:['ZR658','ZR668','ZQ511','ZQ521','QLn420'],category:'行動式／電池／連線',title:'Zebra 行動機｜無法開機、電池、紙不走、藍牙/Wi-Fi、列印品質',severity:'行動機基線',sources:[],summary:'Zebra 行動式機種排查先切開 Battery/Charging、Media/Drive、Printer 自測與 Bluetooth/Wi-Fi。不同世代硬體差異大，深入拆機與電氣量測必須回查該型號維修文件。',keyFacts:['完全不開機先做已知正常 Battery/Charger 交叉。','本機測試正常但 App/Host 不印，優先查配對、網路、Driver/SDK。','熱感列印空白先確認熱感面與 Head。'],engineering:['行動機的跌落、接點氧化、電池膨脹與充電座接觸不良要列入外觀檢查。'],verify:['冷開機正常','充電/續航穩定','本機與無線送印正常','外觀無鬆動'],flow:[['電源/電池','完全不開或續航差。',['電源正常','完全不開','續航差'],'先電池。'],['Battery/Charger 交叉','使用已知正常件。',['恢復','仍異常','不適用'],'先外部。'],['FEED/本機 Test','不經 Host。',['正常','不走紙','空白/品質差'],'分 Printer 本體。'],['Media/Head/Platen','清潔與熱感面確認。',['恢復','仍異常'],'基礎維護。'],['Bluetooth/Wi-Fi/USB','配對/Link/IP/Driver/SDK。',['恢復','仍異常','不適用'],'Host 層。'],['深入硬體','Power/Drive/Mainboard 依機型 Service Manual。',['需送修深入','已修復'],'不跨型號套 Pin。']]});

addRepairKB({id:'toshiba-sa4tm-legacy',brand:'TOSHIBA',models:['SA4TM'],category:'舊機／Sensor／品質',title:'SA4TM｜Paper Jam、Sensor、Ribbon、列印品質、USB/LAN 基線',severity:'舊機基線',sources:['toshiba_manuals'],summary:'SA4TM 已停產，維修應先保存設定與確認耗材/校正，再處理 Sensor、Ribbon、Printhead/Platen 與連線；深入數值依原廠舊機手冊。',keyFacts:['老機先避免不必要 Factory Reset，以免丟失客戶特殊參數。','Paper Jam/定位不準先清 Sensor/Platen 與校正。','固定缺線清潔後仍存在再查 Head。'],engineering:['先備份/列印現有參數，尤其舊客戶可能有特殊 Command/Offset。'],verify:['設定已備份','FEED/定位正常','品質正常','實際工作軟體可印'],flow:[['保存設定/Config','先記錄網路、Sensor、Offset、Emulation。',['完成','無法取得'],'舊機很重要。'],['耗材/Sensor','清潔、位置、紙種與 Calibration。',['恢復','仍異常'],'Paper Jam/跳標優先。'],['Ribbon/品質','裝法、清 Head/Platen、固定測試圖。',['正常','固定缺線','皺碳/太淡'],'分類。'],['Drive','FEED 不走分 Motor 有聲/無聲。',['正常','有聲不走','完全無聲'],'機構優先。'],['USB/LAN','本機正常才查 Driver/Port/IP。',['恢復','仍異常','不適用'],'切開 Host。'],['深入硬體','依 SA4TM 原廠手冊查 Sensor/PSU/Mainboard。',['已修復','需換件'],'不使用其他 B-EX 數值代替。']]});

addRepairKB({id:'sato-clnx-error-map',brand:'SATO',models:['CL4NX Plus'],category:'錯誤碼／Sensor／Cutter',title:'CL4NX Plus｜1007 Head Open、1008 Out of Paper、1009 Ribbon End、1015 Cutter Error',severity:'高價值',sources:['sato_clnx_errors','sato_clnx_hw','sato_clnx_cal'],summary:'CL4NX Plus 原廠有完整錯誤碼表。工程師可直接按錯誤碼切入：1007 Head Open、1008 Out of Paper、1009 Ribbon End、1010 Media Error、1012 Head Error、1015 Cutter Error 等。',keyFacts:['CL4NX Plus 具有固定 Head Open、Ribbon End、Cutter Sensor，Gap/I-Mark Sensor 則可調位置/敏感度。','1008 Out of Paper 需先看 Paper End 使用 Gap 或 I-Mark Sensor。','Cutter Error 先分卡紙/機構與 Sensor/驅動。'],engineering:['錯誤碼比客戶口語更有診斷價值，案件紀錄應直接記 Error No.。','Sensor Auto-calibration 前標籤需依原廠方式處理，避免 I-Mark 正好停在 Sensor 上。'],verify:['錯誤碼清除','連印 100 張','Cutter/Head Open/Sensor 各觸發一次功能正常'],flow:[['記錄 Error No.','不要只記「紅燈」。',['1007 Head Open','1008 Out of Paper','1009 Ribbon End','1010 Media Error','1012 Head Error','1015 Cutter Error','其他'],'直接分流。'],['Head Open','查 Head lock、Head Open Sensor、接頭。',['恢復','仍異常','不適用'],'1007。'],['Paper/Media','查 Paper End Sensor 選擇、Gap/I-Mark、位置、校正。',['恢復','仍異常','不適用'],'1008/1010。'],['Ribbon','確認 Ribbon 路徑、End/Near End Sensor 與模式。',['恢復','仍異常','不適用'],'1009。'],['Cutter','斷電清卡紙→Cutter Sensor/Home→Motor/Drive。',['恢復','仍異常','不適用'],'1015。'],['Head Error','清潔/Head Check/線束後再判 Head 或控制。',['Printhead 方向高','線束/主板方向高','不適用'],'1012。']]});

addRepairKB({id:'sato-cl4sxr-baseline',brand:'SATO',models:['CL4-SXR'],category:'工業型／通用維修',title:'CL4-SXR｜Sensor、Ribbon、Head、Cutter、連線工程基線',severity:'基礎覆蓋',sources:['sato_clnx_errors'],summary:'CL4-SXR 與 CL4NX Plus 並非同機，這裡只提供 SATO 工業機通用工程基線；特定選單、錯誤碼與 Sensor 數值必須依 CL4-SXR 專屬文件。',keyFacts:['先記錄實際錯誤碼與提示文字。','本機 Test 正常再查 Driver/Interface。','Gap/I-Mark、Ribbon、Head Open、Cutter 都應分成獨立 Sensor/機構路徑。'],engineering:['此條目刻意不把 CL4NX Plus 的選單路徑或數值硬套到 CL4-SXR。'],verify:['本機 Test 正常','實際工作正常','錯誤不再復發'],flow:[['記錄畫面錯誤','拍照/抄 Error No.。',['已記錄','無錯誤碼'],'先留下證據。'],['本機 Test/Feed','不經電腦。',['正常','異常'],'切開 Host。'],['耗材/Sensor','紙材、Ribbon、Gap/I-Mark、清潔/校正。',['恢復','仍異常','不適用'],'先基本。'],['品質/Head','清 Head/Platen，固定測試。',['正常','固定缺線','單側淡'],'分類。'],['Cutter/Interface','依症狀分模組。',['恢復','仍異常','不適用'],'不要混查。'],['查 CL4-SXR 專屬手冊深入','進 Pin/電壓/拆機前確認文件。',['已取得','需暫停深入'],'避免跨代誤套。']]});
